/* Tbm02Mapper.selectSessionCd */
SELECT CONCAT('T', DATE_FORMAT(CURDATE(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{gvCmpnyCd}, 'TBM_SESSION_CD'))
FROM DUAL

mapper.sql:
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.DEL_YN = 'N'
  /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기 사업장만 */

    AND A.SITE_CD = #{scopeSiteCd}


    AND A.SITE_CD = #{siteCd}


    AND A.STATUS_CD = #{statusCd}


    AND A.MANAGER_USER_CD = #{managerUserCd}


    AND A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')


    AND DATE(A.INSERT_DATE) >= #{startDate}


    AND DATE(A.INSERT_DATE) <= #{endDate}

mapper.select:
/* Tbm02Mapper.selectSessionListCount */
SELECT COUNT(1)
FROM TB_TBM_SESSION A

/* Tbm02Mapper.selectSessionGuard */
SELECT
	A.SESSION_CD		AS sessionCd
	, A.SITE_CD			AS siteCd
	, A.STATUS_CD		AS statusCd
	, A.MANAGER_USER_CD	AS managerUserCd
FROM TB_TBM_SESSION A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SESSION_CD = #{sessionCd}
  AND A.DEL_YN = 'N'

mapper.insert:
/* Tbm02Mapper.insertSession */
INSERT INTO TB_TBM_SESSION (
	SESSION_CD
	, CMPNY_CD
	, SITE_CD
	, EDU_TYPE_CD
	, TITLE
	, CONTENT_BODY
	, CONTENT_FORMAT_CD
	, STATUS_CD
	, ENTRY_PWD
	, EXIT_PWD
	, MANAGER_USER_CD
	, MANAGER_GPS_LAT
	, MANAGER_GPS_LON
	, GPS_VERIFY_TYPE_CD
	, GPS_VERIFY_RADIUS_M
	, GPS_MANUAL_CONFIRM_YN
	, OPENED_AT
	, DEL_YN
	, INSERT_NO
	, INSERT_DATE
	, UPDATE_NO
	, UPDATE_DATE
) VALUES (
	#{sessionCd}
	, #{gvCmpnyCd}
	, #{siteCd}
	, 'TBM'
	, #{title}
	, #{contentBody}
	, 'RICH_HTML'
	, #{statusCd}
	, #{entryPwd}
	, #{exitPwd}
	, #{managerUserCd}
	, #{managerGpsLat}
	, #{managerGpsLon}
	, IFNULL(#{gpsVerifyTypeCd}, 'AUTO')
	, IFNULL(#{gpsVerifyRadiusM}, 100)
	, #{gpsManualConfirmYn}

		, NOW()
		, NULL

	, 'N'
	, #{gvUserCd}
	, NOW()
	, #{gvUserCd}
	, NOW()
)

mapper.update:
/* Tbm02Mapper.updateSession */
UPDATE TB_TBM_SESSION
SET
	TITLE					= #{title}
	, CONTENT_BODY			= #{contentBody}
	, GPS_VERIFY_TYPE_CD	= IFNULL(#{gpsVerifyTypeCd}, GPS_VERIFY_TYPE_CD)
	, GPS_VERIFY_RADIUS_M	= IFNULL(#{gpsVerifyRadiusM}, GPS_VERIFY_RADIUS_M)
	, MANAGER_GPS_LAT		= #{managerGpsLat}
	, MANAGER_GPS_LON		= #{managerGpsLon}
	, GPS_MANUAL_CONFIRM_YN	= #{gpsManualConfirmYn}
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD IN ('DRAFT', 'OPENED')

