/* Tbm02Mapper.insertSessionContent */
INSERT INTO TB_TBM_SESSION_CONTENT (
	CMPNY_CD
	, SESSION_CD
	, MTRL_CD
	, DISPLAY_ORDER
	, OVERRIDE_DESC
	, INSERT_NO
	, INSERT_DATE
) VALUES (
	#{gvCmpnyCd}
	, #{sessionCd}
	, #{mtrlCd}
	, #{displayOrder}
	, #{overrideDesc}
	, #{gvUserCd}
	, NOW()
)

