mapper.delete:
/* Tbm02Mapper.deleteSessionRisks */
DELETE FROM TB_TBM_SESSION_RISK
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}

mapper.update:
/* Tbm02Mapper.cancelSession */
UPDATE TB_TBM_SESSION
SET
	STATUS_CD		= 'CANCELLED'
	, CANCELLED_AT	= NOW()
	, CANCEL_REASON	= #{cancelReason}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD IN ('DRAFT', 'OPENED')

/* Tbm02Mapper.updateSessionPwd */
UPDATE TB_TBM_SESSION
SET
	ENTRY_PWD		= #{entryPwd}
	, EXIT_PWD		= #{exitPwd}
	, UPDATE_NO		= #{gvUserCd}
	, UPDATE_DATE	= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND DEL_YN = 'N'
  AND STATUS_CD = 'OPENED'

mapper.select:
/* Tbm02Mapper.selectContentOptions */ SELECT A.MTRL_CD AS mtrlCd , A.TITLE AS title , A.MTRL_TYPE AS mtrlType , BD.BAIM_VAL_D_NM AS mtrlTypeNm , A.SITE_CD AS siteCd , CASE WHEN A.SITE_CD IS NULL THEN 'Y' ELSE 'N' END AS isCommonContent , ( SELECT COUNT(I.MTRL_ITEM_CD) FROM TB_TBM_EDU_MTRL_ITEM I WHERE I.MTRL_CD = A.MTRL_CD AND I.USE_YN = 'Y' ) AS itemCnt FROM TB_TBM_EDU_MTRL A LEFT OUTER JOIN TB_BAIM_VAL_D BD ON ( BD.CMPNY_CD = A.CMPNY_CD AND BD.BAIM_VAL_CD = 'COM003' AND BD.BAIM_VAL_D_CD = A.MTRL_TYPE AND BD.USE_YN = 'Y' ) WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.USE_YN = 'Y' /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기사업장+회사공통 */
AND (A.SITE_CD IS NULL OR A.SITE_CD = #{scopeSiteCd})
AND A.SITE_CD IS NULL
AND A.SITE_CD = #{siteCd}
AND A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.SITE_CD IS NOT NULL, A.TITLE

/* Tbm02Mapper.selectRiskOptions */ SELECT A.SITE_CD AS siteCd , A.PROCESS_CD AS processCd , C.BAIM_VAL_D_NM AS processNm , A.RISK_TYPE_CD AS riskTypeCd , D.RISK_TYPE_NM AS riskTypeNm , A.HAZARD_CD AS hazardCd , CASE WHEN A.HAZARD_CD = 'self' THEN A.ASSESSMENT_DESC ELSE E.HAZARD_NM END AS hazardNm , A.ASSESSMENT_CD AS assessmentCd , A.ASSESSMENT_STATUS AS assessmentStatus , B.SYST_VAL_D_NM AS assessmentStatusNm FROM TB_RISK_ASSESSMENT A LEFT OUTER JOIN ( SELECT G.SYST_VAL_D_CD, G.SYST_VAL_D_NM FROM TB_SYST_VAL_D G WHERE G.SYST_VAL_CD = 'SYS011' AND G.USE_YN = 'Y' ) B ON ( A.ASSESSMENT_STATUS = B.SYST_VAL_D_CD ) LEFT OUTER JOIN TB_BAIM_VAL_D C ON ( C.CMPNY_CD = A.CMPNY_CD AND C.BAIM_VAL_CD = 'COM002' AND C.BAIM_VAL_D_CD = A.PROCESS_CD AND C.USE_YN = 'Y' ) LEFT OUTER JOIN TB_RISK_TYPE D ON ( A.CMPNY_CD = D.CMPNY_CD AND A.RISK_TYPE_CD = D.RISK_TYPE_CD ) LEFT OUTER JOIN TB_RISK_SITE_HAZARD E ON ( A.CMPNY_CD = E.CMPNY_CD AND A.RISK_TYPE_CD = E.RISK_TYPE_CD AND A.HAZARD_CD = E.HAZARD_CD ) WHERE A.CMPNY_CD = #{gvCmpnyCd} /* 스코프 필터: master/safe는 회사 전체, 그 외는 자기 사업장만 */
AND A.SITE_CD = #{scopeSiteCd}
AND A.SITE_CD = #{siteCd}
AND A.PROCESS_CD = #{processCd}
ORDER BY A.SITE_CD, A.PROCESS_CD, A.RISK_TYPE_CD, A.HAZARD_CD
